390→+		if readErr != nil {
391→+			transcript = nil
392→+		}
393→+	}
394→+	if len(transcript) == 0 {
395→+		return nil // No transcript to write
396→+	}
397→+
398→+	if err := validateWriteOpts(opts); err != nil {
399→+		return err

400→+	}
401→+
402→+	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
403→+	if err := s.ensureRef(refName); err != nil {
