412→+	basePath := opts.CheckpointID.Path() + "/"
413→+	checkpointPath := opts.CheckpointID.Path()
414→+	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
415→+
416→+	// Read existing entries at this checkpoint's shard path (accumulate, don't replace)
417→+	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
418→+	if err != nil {
