525→+// ensureRef ensures that a custom ref exists, creating an orphan commit
526→+// with an empty tree if it does not.
527→+func (s *V2GitStore) ensureRef(refName plumbing.ReferenceName) error {
528→+	_, err := s.repo.Reference(refName, true)
529→+	if err == nil {
530→+		return nil // Already exists
531→+	}
532→+
533→+	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
534→+	if err != nil {
535→+		return fmt.Errorf("failed to build empty tree: %w", err)
536→+	}
537→+
538→+	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
539→+	commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
540→+	if err != nil {
541→+		return fmt.Errorf("failed to create initial commit: %w", err)
542→+	}
543→+
544→+	ref := plumbing.NewHashReference(refName, commitHash)
545→+	if err := s.repo.Storer.SetReference(ref); err != nil {
546→+		return fmt.Errorf("failed to set ref %s: %w", refName, err)
547→+	}
548→+
549→+	return nil
550→+}
551→+
552→+// getRefState returns the parent commit hash and root tree hash for a ref.
553→+func (s *V2GitStore) getRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
554→+	ref, err := s.repo.Reference(refName, true)
555→+	if err != nil {
556→+		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
557→+	}
558→+
559→+	commit, err := s.repo.CommitObject(ref.Hash())
560→+	if err != nil {
561→+		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
562→+	}
563→+
564→+	return ref.Hash(), commit.TreeHash, nil
565→+}
566→+
567→+// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
568→+func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
569→+	commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
570→+	if err != nil {
571→+		return fmt.Errorf("failed to create commit: %w", err)
572→+	}
573→+
574→+	ref := plumbing.NewHashReference(refName, commitHash)
575→+	if err := s.repo.Storer.SetReference(ref); err != nil {
576→+		return fmt.Errorf("failed to update ref %s: %w", refName, err)
577→+	}
578→+
579→+	return nil
580→+}
