 47→// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
 48→// Called at stop time to finalize checkpoints with the complete session transcript.
 49→//
 50→// On /main: replaces prompts (transcript is not stored there).
 51→// On /full/current: replaces the raw transcript (if provided).
 52→//
 53→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
 54→func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
 55→	if opts.CheckpointID.IsEmpty() {
 56→		return errors.New("invalid update options: checkpoint ID is required")
 57→	}
 58→
 59→	sessionIndex, err := s.updateCommittedMain(ctx, opts)
 60→	if err != nil {
 61→		return fmt.Errorf("v2 /main update failed: %w", err)
 62→	}
 63→
 64→	if len(opts.Transcript) > 0 {
 65→		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 66→			return fmt.Errorf("v2 /full/current update failed: %w", err)
 67→		}
 68→	}
 69→
 70→	return nil
 71→}
