 73→// updateCommittedMain updates prompts on the /main ref for an existing checkpoint.
 74→// Returns the session index for coordination with /full/current.
 75→func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
 76→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 77→	parentHash, rootTreeHash, err := s.getRefState(refName)
 78→	if err != nil {
 79→		return 0, ErrCheckpointNotFound
 80→	}
 81→
 82→	basePath := opts.CheckpointID.Path() + "/"
 83→	checkpointPath := opts.CheckpointID.Path()
 84→
 85→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 86→	if err != nil {
 87→		return 0, err
 88→	}
 89→
 90→	// Read root summary to find session index
 91→	rootMetadataPath := basePath + paths.MetadataFileName
 92→	entry, exists := entries[rootMetadataPath]
 93→	if !exists {
 94→		return 0, ErrCheckpointNotFound
 95→	}
 96→
 97→	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
 98→	if err != nil {
 99→		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
100→	}
101→	if len(summary.Sessions) == 0 {
102→		return 0, ErrCheckpointNotFound
103→	}
104→
105→	// Find session index by ID, fall back to latest
106→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
107→	if sessionIndex >= len(summary.Sessions) {
108→		// findSessionIndex returns next-available when not found; fall back to latest
109→		sessionIndex = len(summary.Sessions) - 1
110→		logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
111→			slog.String("session_id", opts.SessionID),
112→			slog.String("checkpoint_id", string(opts.CheckpointID)),
113→			slog.Int("fallback_index", sessionIndex),
114→		)
115→	}
116→
117→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
118→
119→	// Replace prompts
120→	if len(opts.Prompts) > 0 {
121→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
122→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
123→		if err != nil {
124→			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
125→		}
126→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
127→			Name: sessionPath + paths.PromptFileName,
128→			Mode: filemode.Regular,
129→			Hash: blobHash,
130→		}
131→	}
132→
133→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
134→	if err != nil {
135→		return 0, err
136→	}
137→
138→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
139→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
140→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
141→		return 0, err
142→	}
143→
144→	return sessionIndex, nil
145→}
