147→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
148→// on /full/current while preserving other checkpoints' transcripts in the tree.
149→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
150→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
151→	if err := s.ensureRef(refName); err != nil {
152→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
153→	}
154→
155→	parentHash, rootTreeHash, err := s.getRefState(refName)
156→	if err != nil {
157→		return err
158→	}
159→
160→	basePath := opts.CheckpointID.Path() + "/"
161→	checkpointPath := opts.CheckpointID.Path()
162→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
163→
164→	// Read existing entries and replace transcript for this checkpoint only
165→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
166→	if err != nil {
167→		return err
168→	}
169→
170→	// Clear existing transcript entries at this session path before writing new ones
171→	for key := range entries {
172→		if strings.HasPrefix(key, sessionPath) {
173→			delete(entries, key)
174→		}
175→	}
176→
177→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
178→	if err != nil {
179→		return err
180→	}
181→
182→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
183→		return err
184→	}
185→
186→	// Splice into existing root tree (preserves other checkpoints' transcripts)
187→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
188→	if err != nil {
189→		return err
190→	}
191→
192→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
193→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
194→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
195→}
