356→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
357→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
358→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
359→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
360→	if err != nil {
361→		return err
362→	}
363→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
364→		Name: sessionPath + paths.ContentHashFileName,
365→		Mode: filemode.Regular,
366→		Hash: hashBlob,
367→	}
368→	return nil
369→}
