11→// V2GitStore provides checkpoint storage operations for the v2 ref layout.
12→// It writes to two custom refs under refs/entire/:
13→//   - /main: permanent metadata + compact transcripts
14→//   - /full/current: active generation of raw transcripts
15→//
16→// V2GitStore is separate from GitStore (v1) to keep concerns isolated
17→// and simplify future v1 removal. It composes GitStore internally to
18→// reuse ref-agnostic entry-building helpers (tree surgery, session
19→// indexing, summary aggregation).
20→type V2GitStore struct {
21→	repo *git.Repository
22→	gs   *GitStore // shared entry-building helpers (same package)
23→}
24→
25→// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
26→func NewV2GitStore(repo *git.Repository) *V2GitStore {
27→	return &V2GitStore{
28→		repo: repo,
29→		gs:   &GitStore{repo: repo},
30→	}
31→}
32→
33→// ensureRef ensures that a custom ref exists, creating an orphan commit
34→// with an empty tree if it does not.
35→func (s *V2GitStore) ensureRef(refName plumbing.ReferenceName) error {
36→	_, err := s.repo.Reference(refName, true)
37→	if err == nil {
38→		return nil // Already exists
39→	}
40→
41→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
42→	if err != nil {
43→		return fmt.Errorf("failed to build empty tree: %w", err)
44→	}
45→
46→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
47→	commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
48→	if err != nil {
49→		return fmt.Errorf("failed to create initial commit: %w", err)
50→	}
51→
52→	ref := plumbing.NewHashReference(refName, commitHash)
53→	if err := s.repo.Storer.SetReference(ref); err != nil {
54→		return fmt.Errorf("failed to set ref %s: %w", refName, err)
55→	}
56→
57→	return nil
58→}
59→
60→// getRefState returns the parent commit hash and root tree hash for a ref.
61→func (s *V2GitStore) getRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
62→	ref, err := s.repo.Reference(refName, true)
63→	if err != nil {
64→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
65→	}
66→
67→	commit, err := s.repo.CommitObject(ref.Hash())
68→	if err != nil {
69→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
70→	}
71→
72→	return ref.Hash(), commit.TreeHash, nil
73→}
74→
75→// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
76→func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
77→	commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
78→	if err != nil {
79→		return fmt.Errorf("failed to create commit: %w", err)
80→	}
81→
82→	ref := plumbing.NewHashReference(refName, commitHash)
83→	if err := s.repo.Storer.SetReference(ref); err != nil {
84→		return fmt.Errorf("failed to update ref %s: %w", refName, err)
85→	}
86→
87→	return nil
88→}
